-- Synthetische, idempotente fixture voor Liquid HR Operations B.V.
-- Alle employee_number-waarden beginnen met OPS-TEST- en mogen veilig opnieuw worden geladen.
  create temporary table ops_fixture_employees (id uuid primary key) on commit drop;
  insert into ops_fixture_employees (id)
  select md5('liquidhr-ops-test:employee:' || n)::uuid
  from generate_series(1, 10) n;

  -- Verwijder alleen de eerder geladen OPS-TEST-fixture en haar afhankelijke tijdlijnen.
  delete from public.employment_terminations
  where employee_id in (select id from ops_fixture_employees)
     or employee_id in (select id from public.employees where employee_number like 'OPS-TEST-%');
  delete from public.employment_income_relationships
  where employee_id in (select id from ops_fixture_employees)
     or employee_id in (select id from public.employees where employee_number like 'OPS-TEST-%');
  delete from public.employee_organizations
  where employee_id in (select id from ops_fixture_employees)
     or employee_id in (select id from public.employees where employee_number like 'OPS-TEST-%');
  delete from public.employment_labor_conditions
  where employee_id in (select id from ops_fixture_employees)
     or employee_id in (select id from public.employees where employee_number like 'OPS-TEST-%');
  delete from public.employment_schedules
  where employee_id in (select id from ops_fixture_employees)
     or employee_id in (select id from public.employees where employee_number like 'OPS-TEST-%');
  delete from public.employment_salaries
  where employee_id in (select id from ops_fixture_employees)
     or employee_id in (select id from public.employees where employee_number like 'OPS-TEST-%');
  delete from public.employment_cost_allocations
  where employee_id in (select id from ops_fixture_employees)
     or employee_id in (select id from public.employees where employee_number like 'OPS-TEST-%');
  delete from public.employment_change_sets
  where employee_id in (select id from ops_fixture_employees)
     or employee_id in (select id from public.employees where employee_number like 'OPS-TEST-%');
  delete from public.employment_contracts
  where employee_id in (select id from ops_fixture_employees)
     or employee_id in (select id from public.employees where employee_number like 'OPS-TEST-%');
  delete from public.income_relationships
  where employee_id in (select id from ops_fixture_employees)
     or employee_id in (select id from public.employees where employee_number like 'OPS-TEST-%');
  delete from public.employments
  where employee_id in (select id from ops_fixture_employees)
     or employee_id in (select id from public.employees where employee_number like 'OPS-TEST-%');
  delete from public.employee_administration_assignments
  where employee_id in (select id from ops_fixture_employees)
     or employee_id in (select id from public.employees where employee_number like 'OPS-TEST-%');
  delete from public.employees
  where id in (select id from ops_fixture_employees) or employee_number like 'OPS-TEST-%';

