  -- EÃ©n inkomstenverhouding per dienstverband; IKV-nummers zijn onderling uniek binnen de fixture.
  insert into public.income_relationships (id, tenant_id, administration_id, employee_id, payroll_tax_subnumber, ikv_number, relationship_type, starts_on, ends_on, reporting_status)
  select md5('liquidhr-ops-test:income:' || e.employment_number)::uuid, e.tenant_id, e.administration_id, e.employee_id,
    'OPS-' || lpad(row_number() over (order by e.employment_number)::text, 2, '0'), row_number() over (order by e.employment_number)::integer,
    'EMPLOYMENT', e.starts_on, e.ends_on, case when e.ends_on is null then 'READY'::public.payroll_reporting_status else 'CLOSED'::public.payroll_reporting_status end
  from public.employments e where e.employment_number like 'OPS-TEST-%';

  insert into public.employment_income_relationships (id, tenant_id, administration_id, employee_id, employment_id, income_relationship_id, valid_from, valid_until)
  select md5('liquidhr-ops-test:income-link:' || e.employment_number)::uuid, e.tenant_id, e.administration_id, e.employee_id, e.id,
    md5('liquidhr-ops-test:income:' || e.employment_number)::uuid, e.starts_on, case when e.ends_on is null then null else e.ends_on + 1 end
  from public.employments e where e.employment_number like 'OPS-TEST-%';

